124	/// Route a service subcommand to the appropriate handler.
125	pub fn handle_command(command: &ServiceAction) -> Result<()> {
126	    match command {
127	        ServiceAction::Install => install(),
128	        ServiceAction::Start => start(),
129	        ServiceAction::Stop => stop(),
130	        ServiceAction::Status => status(),
131	        ServiceAction::Uninstall => uninstall(),
132	    }
133	}
