468	fn macos_plist_path() -> Result<PathBuf> {
469	    let home = dirs::home_dir().context("could not find home directory")?;
470	    Ok(home
471	        .join("Library")
472	        .join("LaunchAgents")
473	        .join(format!("{SERVICE_LABEL}.plist")))
474	}
475	
476	fn linux_unit_path() -> Result<PathBuf> {
477	    Ok(linux_systemd_unit_dir()?.join(SYSTEMD_UNIT))
478	}
479	
480	fn linux_xmpp_bridge_unit_path() -> Result<PathBuf> {
481	    Ok(linux_systemd_unit_dir()?.join(SYSTEMD_XMPP_BRIDGE_UNIT))
482	}
483	
484	fn linux_legacy_unit_path() -> Result<PathBuf> {
485	    Ok(linux_systemd_unit_dir()?.join(LEGACY_SYSTEMD_UNIT))
486	}
487	
488	fn linux_systemd_unit_dir() -> Result<PathBuf> {
489	    let home = dirs::home_dir().context("could not find home directory")?;
490	    Ok(home.join(".config").join("systemd").join("user"))
491	}
492	
493	fn linux_openrc_init_path(name: &str) -> PathBuf {
494	    PathBuf::from("/etc/init.d").join(name)
495	}
496	
497	fn linux_openrc_confd_path(name: &str) -> PathBuf {
498	    PathBuf::from("/etc/conf.d").join(name)
499	}

799	fn status_linux_openrc() -> Result<()> {
800	    let file = linux_openrc_init_path(OPENRC_UNIT);
801	    if !file.exists() {
802	        println!("Service state: not installed");
803	        println!("Unit: {}", file.display());
804	        return Ok(());
805	    }
806	
807	    let state = run_capture(Command::new("rc-service").args([OPENRC_UNIT, "status"]))
808	        .unwrap_or_else(|_| "unknown".into());
809	    println!("Service state: {}", state.trim());
810	    println!("Unit: {}", file.display());
811	
812	    let bridge_file = linux_openrc_init_path(OPENRC_XMPP_BRIDGE_UNIT);
813	    if bridge_file.exists() {
814	        let bridge_state =
815	            run_capture(Command::new("rc-service").args([OPENRC_XMPP_BRIDGE_UNIT, "status"]))
816	                .unwrap_or_else(|_| "unknown".into());
817	        println!("XMPP bridge state: {}", bridge_state.trim());
818	        println!("XMPP bridge unit: {}", bridge_file.display());
819	    }
820	
821	    Ok(())
822	}
823	
824	fn uninstall_linux_systemd_user() -> Result<()> {
825	    let file = linux_unit_path()?;
826	    let bridge_file = linux_xmpp_bridge_unit_path()?;
827	    let bridge_installed = bridge_file.exists();
828	    run_checked(Command::new("systemctl").args(["--user", "disable", SYSTEMD_UNIT])).ok();
829	    if file.exists() {
830	        std::fs::remove_file(&file)
831	            .with_context(|| format!("failed to remove {}", file.display()))?;
832	    }
833	    run_checked(Command::new("systemctl").args(["--user", "disable", SYSTEMD_XMPP_BRIDGE_UNIT]))
834	        .ok();
835	    if bridge_file.exists() {
836	        std::fs::remove_file(&bridge_file)
837	            .with_context(|| format!("failed to remove {}", bridge_file.display()))?;
838	    }
839	    run_checked(Command::new("systemctl").args(["--user", "daemon-reload"])).ok();
840	    println!("Service uninstalled ({})", file.display());
841	    if bridge_installed {
842	        println!(
843	            "XMPP bridge service uninstalled ({})",
844	            bridge_file.display()
845	        );
846	    }
847	    Ok(())
848	}
849	
850	fn uninstall_linux_openrc() -> Result<()> {
851	    ensure_openrc_root("uninstall")?;
852	
853	    let file = linux_openrc_init_path(OPENRC_UNIT);
854	    let conf = linux_openrc_confd_path(OPENRC_UNIT);
855	    let bridge_file = linux_openrc_init_path(OPENRC_XMPP_BRIDGE_UNIT);
856	    let bridge_conf = linux_openrc_confd_path(OPENRC_XMPP_BRIDGE_UNIT);
857	
858	    run_checked(Command::new("rc-update").args(["del", OPENRC_UNIT, "default"])).ok();
859	    run_checked(Command::new("rc-update").args(["del", OPENRC_XMPP_BRIDGE_UNIT, "default"])).ok();
860	
861	    if file.exists() {
862	        std::fs::remove_file(&file)
863	            .with_context(|| format!("failed to remove {}", file.display()))?;
864	    }
865	    if conf.exists() {
866	        std::fs::remove_file(&conf)
867	            .with_context(|| format!("failed to remove {}", conf.display()))?;
868	    }
869	    if bridge_file.exists() {
870	        std::fs::remove_file(&bridge_file)
871	            .with_context(|| format!("failed to remove {}", bridge_file.display()))?;
872	    }
873	    if bridge_conf.exists() {
874	        std::fs::remove_file(&bridge_conf)
875	            .with_context(|| format!("failed to remove {}", bridge_conf.display()))?;
876	    }
877	
878	    println!("Service uninstalled ({})", file.display());
879	    println!(
880	        "Preserved environment files under {}",
881	        linux_openrc_env_dir().display()
882	    );
883	    Ok(())
884	}
