886	// ── Shell helpers ───────────────────────────────────────────────
887	
888	fn run_checked(command: &mut Command) -> Result<()> {
889	    let output = command.output().context("failed to spawn command")?;
890	    if !output.status.success() {
891	        let stderr = String::from_utf8_lossy(&output.stderr);
892	        bail!("command failed: {}", stderr.trim());
893	    }
894	    Ok(())
895	}
